<template><div class="my-feedback"><h1>{{ t('feedback.myFeedback') }}</h1><t-table row-key="id" :data="items" :columns="columns" :loading="loading" /></div></template>
<script setup lang="ts">import {onMounted,ref,computed} from 'vue';import {useI18n} from 'vue-i18n';import {listMyFeedback,type AnswerFeedback} from '@/api/answer-feedback';const {t}=useI18n();const items=ref<AnswerFeedback[]>([]);const loading=ref(false);const columns=computed(()=>[{colKey:'status',title:t('feedback.status'),cell:(h:any,{row}:any)=>h('span',t(`feedback.statuses.${row.status}`))},{colKey:'category',title:t('feedback.categoryLabel'),cell:(h:any,{row}:any)=>h('span',t(`feedback.categories.${row.category}`))},{colKey:'description',title:t('feedback.descriptionLabel'),ellipsis:true},{colKey:'created_at',title:t('feedback.createdAt')}]);onMounted(async()=>{loading.value=true;try{const r=await listMyFeedback(1,100);items.value=r.data||[]}finally{loading.value=false}})</script>
<style scoped>.my-feedback{padding:28px;max-width:1200px;margin:auto}.my-feedback h1{margin-bottom:24px}</style>
